import pandas as pd
import numpy as np
from scipy import stats
import os

# Load all available experiments
files = {
    'exp1': experiment_1_csv,
    'exp3': experiment_3_csv, 
    'exp5': experiment_5_csv,
    'exp8': experiment_8_csv,
    'exp12': experiment_12_csv
}

dfs = {}
for name, path in files.items():
    if os.path.exists(path):
        dfs[name] = pd.read_csv(path)
        print(f"\n{name} columns: {list(dfs[name].columns)}")
        print(f"{name} shape: {dfs[name].shape}")
        print(dfs[name].describe().round(2))

# Check if JobThroughput exists in all
for name, df in dfs.items():
    if 'JobThroughput' in df.columns:
        print(f"\n{name} has JobThroughput (n={len(df)})")
    else:
        print(f"\n{name} does NOT have JobThroughput, available: {df.columns.tolist()}")

# Combine all data where possible
if dfs:
    # Show which numeric columns exist across datasets
    all_cols = set()
    for df in dfs.values():
        all_cols.update(df.select_dtypes(include=[np.number]).columns)
    print(f"\nAll numeric columns across datasets: {sorted(all_cols)}")
